import Openai from "openai";

const client = new Openai({
  apiKey: process.env["OPENAI_API_KEY"],
});

const result = await client.realtime.transcriptionSessions.create({ turn_detection: { type: "server_vad", threshold: 1, prefix_padding_ms: 1, silence_duration_ms: 1 }, input_audio_noise_reduction: { type: "near_field" }, input_audio_format: "pcm16", input_audio_transcription: { model: "string", language: "string", prompt: "string", delay: "minimal" }, include: ["item.input_audio_transcription.logprobs"] });
console.log(result);
